const CACHE_NAME = "signalsafe-v0.3.1-research-entry-consent";
const ASSETS = ["./","./index.html","./compat.mjs","./bootstrap.mjs","./questions.mjs","./research.mjs","./research-consent.mjs","./scoring.mjs","./storage.mjs","./manifest.webmanifest","./icon.svg","./styles/01.css","./styles/02.css","./styles/03-v03.css","./styles/04-v03-insights.css","./styles/05-v031-consent.css","./app-parts/app-core.js","./app-parts/app-home.js","./app-parts/app-quick.js","./app-parts/app-assessment.js","./app-parts/app-insights.js","./app-parts/app-runtime.js","./app-parts/app-v03.js","./app-parts/app-v03-insights.js","./app-parts/app-v03-feedback.js","./app-parts/app-v031-consent.js","./question-data/shared.mjs","./question-data/quick.mjs","./question-data/pre-a.mjs","./question-data/pre-b.mjs","./question-data/training-a.mjs","./question-data/training-b.mjs","./question-data/post-a.mjs","./question-data/post-b.mjs"];
self.addEventListener("install",event=>{event.waitUntil(caches.open(CACHE_NAME).then(cache=>cache.addAll(ASSETS)));self.skipWaiting();});
self.addEventListener("activate",event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE_NAME).map(key=>caches.delete(key)))));self.clients.claim();});
self.addEventListener("fetch",event=>{if(event.request.method!=="GET")return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE_NAME).then(cache=>cache.put(event.request,copy)).catch(()=>{});return response;}).catch(()=>caches.match(event.request).then(cached=>cached||caches.match("./index.html"))));});
